// seed: tests/seed.spec.ts
// Прод, только чтение: все URL sitemap, сырой HTML через request API, параллельно по 8.
import { test, expect } from '@playwright/test';
import { readSitemap, rawHtml, titleOf, rootHtml, seoBody, h1s, labeled, pool } from './ssr-seo.helpers';

test.describe('SSR и SEO публичных страниц — метаданные', () => {
  test('title уникален по всем URL sitemap; формат title объявления и категории #b489db @desktop @prod-safe', async ({ request }) => {
    test.setTimeout(10 * 60_000);
    const sm = await readSitemap(request);
    expect(sm.all.length, 'URL в sitemap').toBeGreaterThan(0);

    const rows = await pool(
      sm.all,
      async (loc) => {
        const u = new URL(loc);
        const problems: string[] = [];
        const { status, html } = await rawHtml(request, u.pathname + u.search);
        if (status !== 200) return { loc, title: '', problems: [`HTTP ${status}`] };
        const title = titleOf(html) ?? '';
        if (!title) problems.push('пустой title');

        const id = u.pathname === '/businessdetail' ? u.searchParams.get('id') : null;
        const cat = u.pathname === '/search' ? u.searchParams.get('category') : null;
        if (id) {
          // «<название> – <категория>, <город> | Biz4Sale»; без одного поля — «<название> – <что есть> | Biz4Sale»;
          // без обоих — «<название> – מודעה <id8> | Biz4Sale». Поля — из SSR-блока страницы.
          const seo = seoBody(rootHtml(html) ?? '')?.html ?? '';
          const name = h1s(seo)[0] ?? '';
          const c = labeled(seo, 'קטגוריה:');
          const l = labeled(seo, 'מיקום:');
          const tail = c && l ? `${c}, ${l}` : c || l || `מודעה ${id.slice(0, 8)}`;
          const expected = `${name} – ${tail} | Biz4Sale`;
          if (title !== expected) problems.push(`title «${title}» ≠ «${expected}»`);
        } else if (cat) {
          const expected = `עסקים למכירה בקטגוריית ${cat} | Biz4Sale`;
          if (title !== expected) problems.push(`title «${title}» ≠ «${expected}»`);
        }
        return { loc, title, problems };
      },
      (loc, e) => ({ loc, title: '', problems: [`ошибка запроса: ${e.message.split('\n')[0]}`] }),
    );

    const bad = rows.filter((r) => r.problems.length);
    expect(bad.map((r) => `${r.loc}: ${r.problems.join('; ')}`), `нарушителей ${bad.length}/${rows.length}`).toEqual([]);

    const byTitle = new Map<string, string[]>();
    for (const r of rows) if (r.title) byTitle.set(r.title, [...(byTitle.get(r.title) ?? []), r.loc]);
    const dups = [...byTitle].filter(([, locs]) => locs.length > 1).map(([t, locs]) => `«${t}»: ${locs.join(' , ')}`);
    expect(dups, 'дубли title').toEqual([]);
  });
});
